//--|🠊 ArchiveHeader.tsx 🠈|--\\
//--|🠋 Dependencies 🠋|--\\
import React, { useEffect, useState } from 'react';

//--|🠋 Components 🠋|--\\
import MenuSwipe from '../../../components/Menu/swipe/Menu.swipe';
import MenuSelect from '../../../components/Menu/select/Menu.select';
import DivisionConveyor from '../../../components/Division/conveyor/Division.conveyor';
import NavigationDefault from '../../../components/Navigation/default/Navigation.default';

//--|🠋 Functions 🠋|--\\
import blockViews from '../../containers';
import { lockBlock } from '../../../scripts/Header';
import { stripBrackets, checkScreen, loadAsset, loadPages } from '../../../../scripts';

interface InfoProps {
  info: {
    blockName: '<header>' | string;
    labelName: '(default)' | string;
    pageName: '[components]' | string;
  };
}
function ArchiveHeader({ info }: InfoProps): JSX.Element {
  const [getOrientation, setOrientation] = useState<'landscape' | 'portrait'>(
    window.matchMedia('(orientation: landscape)').matches ? 'landscape' : 'portrait',
  ); //--|🠈 Updates state when the orientation changes 🠈|--\\

  let blockName = stripBrackets(info.blockName, '<>') as 'header';
  let labelName = stripBrackets(info.labelName, '()') as 'default';
  let pageName = stripBrackets(info.pageName, '[]') as 'components';

  useEffect(() => {
    //--|🟨|--\\
    return checkScreen(setOrientation);
  }, [pageName, blockName, labelName]);

  let blurName: string = 'obnubilate';
  let stateName: 'expanded' | 'unfolded' | 'collapsed' | 'squaring';
  switch (getOrientation) {
    case 'landscape':
      stateName = 'unfolded';
      return (
        <header
          id={`${pageName}-${blockName}`}
          className={`${blurName} ${labelName}-${blockName} ${stateName}`}
          onMouseEnter={(event) => {
            blockViews(event.currentTarget, pageName, 'header', 'unfold');
            blockViews(event.currentTarget, pageName, 'leftbar', 'unfold');
          }}
        >
          <section className={`${blockName}-foreground`}>
            <NavigationDefault
              //--|🠊 <nav class="default-header_navigation-default"/> 🠈|--\\
              info={{
                pageName: pageName,
                blockName: blockName,
                labelName: labelName,
              }}
              style={{
                color: '(mono)',
                view: 'top-lef',
                shade: '~light~',
                image: loadAsset('-svg-', '/archive-images/my-signature/signature-icon/primary-dark') as string,
              }}
              cases={{
                view: undefined,
                image: undefined,
                tasks: {
                  onClick: (view) => {
                    switch (view) {
                      case 'top-lef':
                        lockBlock(pageName, 'header');
                        lockBlock(pageName, 'leftbar');
                        break;
                    }
                  },
                },
              }}
            />
            <DivisionConveyor
              //--|🠊 <div class="elements-header_conveyor-default"/> 🠈|--\\
              cases={{
                axis: '[y]',
                call: DeskMenuSwipes as React.ComponentType<InfoProps>,
              }}
              info={{
                labelName: 'elements',
                blockName: blockName as 'header',
                pageName: pageName as 'components',
              }}
            />
          </section>
          <figure className={`${blockName}-midground`}></figure>
          <div className={`${blockName}-background`}>
            <header>
              <div className="top-header"></div>
              <div className="bot-header"></div>
            </header>
          </div>
        </header>
      );
    case 'portrait':
      stateName = 'unfolded';
      return (
        <header
          id={`${pageName}-${blockName}`}
          className={`${blurName} ${labelName}-${blockName} ${stateName}`}
          onMouseEnter={(event) => {
            blockViews(event.currentTarget, pageName, 'header', 'unfold');
            blockViews(event.currentTarget, pageName, 'leftbar', 'unfold');
          }}
        >
          <section className={`${blockName}-foreground`}>
            <NavigationDefault
              //--|🠊 <nav class="default-footer_navigation-default"/> 🠈|--\\
              info={{
                pageName: pageName,
                blockName: blockName,
                labelName: labelName,
              }}
              style={{
                color: '(mono)',
                view: 'top-lef',
                shade: '~light~',
                image: loadAsset('-svg-', '/archive-images/trinity-apps/tralogfin/trinity-apps') as string,
              }}
              cases={{
                view: undefined,
                image: undefined,
                tasks: {
                  onClick: (view) => {
                    switch (view) {
                      case 'top-lef':
                        return loadPages('landing');
                    }
                  },
                },
              }}
            />
            <MenuSelect
              info={{
                blockName: blockName as 'main',
                pageName: pageName as 'components',
                labelName: `${pageName}-applications` as string,
              }}
              style={{
                align: '-mid-',
                view: 'top-cen',
                shade: '~light~',
                color: ['(green)', '(blue)', '(red)'],

                image: [
                  loadAsset('-svg-', '/archive-images/trinity-apps/track-a-day/primary-medium'),
                  loadAsset('-svg-', '/archive-images/trinity-apps/log-a-ticket/primary-medium'),
                  loadAsset('-svg-', '/archive-images/trinity-apps/find-a-link/primary-medium'),
                ] as Array<string>,
                size: '<h4>',
              }}
              cases={{
                pages: 3,
                axis: '[x]',
                link: undefined,
                task: [() => loadPages('overtime'), () => loadPages('ticketing'), () => loadPages('hyperlink')],
              }}
            />
          </section>
          <figure className={`${blockName}-midground`}></figure>
          <div className={`${blockName}-background`}>
            <header>
              <div className="top-header"></div>
              <div className="bot-header"></div>
            </header>
          </div>
        </header>
      );
  }
}
const DeskMenuSwipes: React.FC<InfoProps> = ({ info }) => {
  const blockName = info.blockName as 'header';
  const labelName = info.labelName as 'default';
  const pageName = info.pageName as 'components';

  let styleShade = '~light~' as '~dark~' | '~light~';
  let styleColor = '(mono)' as '(red)' | '(green)' | '(blue)' | '(mono)';
  let styleView = 'def' as '-def-' | '-lef-' | '-rig-' | '-cen-' | '-top-' | '-bot-' | '-mid-';
  return (
    <>
      <MenuSwipe
        info={{
          labelName: 'article',
          blockName: blockName as 'header',
          pageName: pageName as 'components',
        }}
        style={{
          view: styleView,
          color: styleColor,
          shade: styleShade,
        }}
        cases={{
          axis: '[x]',
          titles: ['<Article_Updates>', '<Article_Loading>'] as Array<string>,
        }}
      />
      <MenuSwipe
        info={{
          labelName: 'aside',
          blockName: blockName as 'header',
          pageName: pageName as 'components',
        }}
        style={{
          view: styleView,
          color: styleColor,
          shade: styleShade,
        }}
        cases={{
          axis: '[x]',
          titles: ['<Aside_Characters>'] as Array<string>,
        }}
      />
      <MenuSwipe
        info={{
          labelName: 'button',
          blockName: blockName as 'header',
          pageName: pageName as 'components',
        }}
        style={{
          view: styleView,
          color: styleColor,
          shade: styleShade,
        }}
        cases={{
          axis: '[x]',
          titles: ['<Button_Default>', '<Button_Routing>'] as Array<string>,
        }}
      />
      <MenuSwipe
        info={{
          labelName: 'division',
          blockName: blockName as 'header',
          pageName: pageName as 'components',
        }}
        style={{
          view: styleView,
          color: styleColor,
          shade: styleShade,
        }}
        cases={{
          axis: '[x]',
          titles: ['<Division_Testing>'] as Array<string>,
        }}
      />
      <MenuSwipe
        info={{
          labelName: 'figure',
          blockName: blockName as 'header',
          pageName: pageName as 'components',
        }}
        style={{
          view: styleView,
          color: styleColor,
          shade: styleShade,
        }}
        cases={{
          axis: '[x]',
          titles: ['<Figure_Default>'] as Array<string>,
        }}
      />
      <MenuSwipe
        info={{
          labelName: 'menu',
          blockName: blockName as 'header',
          pageName: pageName as 'components',
        }}
        style={{
          view: styleView,
          color: styleColor,
          shade: styleShade,
        }}
        cases={{
          axis: '[x]',
          titles: ['<Menu_Swipe>', '<Menu_Select>', '<Menu_Scroll>'] as Array<string>,
        }}
      />
      <MenuSwipe
        info={{
          labelName: 'navigation',
          blockName: blockName as 'header',
          pageName: pageName as 'components',
        }}
        style={{
          view: styleView,
          color: styleColor,
          shade: styleShade,
        }}
        cases={{
          axis: '[x]',
          titles: ['<Navigation_Default>'] as Array<string>,
        }}
      />
      <MenuSwipe
        info={{
          labelName: 'section',
          blockName: blockName as 'header',
          pageName: pageName as 'components',
        }}
        style={{
          view: styleView,
          color: styleColor,
          shade: styleShade,
        }}
        cases={{
          axis: '[x]',
          titles: ['<Section_Default>'] as Array<string>,
        }}
      />
      <MenuSwipe
        info={{
          labelName: 'table',
          blockName: blockName as 'header',
          pageName: pageName as 'components',
        }}
        style={{
          view: styleView,
          color: styleColor,
          shade: styleShade,
        }}
        cases={{
          axis: '[x]',
          titles: ['<Table_Default>'] as Array<string>,
        }}
      />
      <MenuSwipe
        info={{
          labelName: 'time',
          blockName: blockName as 'header',
          pageName: pageName as 'components',
        }}
        style={{
          view: styleView,
          color: styleColor,
          shade: styleShade,
        }}
        cases={{
          axis: '[x]',
          titles: ['<Time_Default>'] as Array<string>,
        }}
      />
    </>
  );
};
export default ArchiveHeader;
